#pragma once
// Palette entries for the wheeled-vehicle nodes. NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after
// pin()/attr() are defined, and calls appendVehicleNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphVehicleNodeTable.cs pin for pin
// (docs/plans/wave9/VISUAL_SCRIPTING_CSHARP_SYNC.md section 2.2). A vehicle is its integer handle (0 = none), the way an
// entity is. Create Car builds the default car (four wheels, front steered, rear driven) and the entity that follows it.

inline void appendVehicleNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AN_VehicleCreateCar", "Vehicle Create Car", "Vehicle", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("yaw", "float", false), pin("massKg", "float", false, "1500"),
        pin("then", "exec", true), pin("vehicle", "int", true), pin("entity", "int", true)}});
    t.push_back({"AN_VehicleSetInput", "Vehicle Set Input", "Vehicle", {
        pin("exec", "exec", false), pin("vehicle", "int", false), pin("throttle", "float", false), pin("steer", "float", false),
        pin("brake", "float", false), pin("handbrake", "float", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleGetState", "Vehicle Get State", "Vehicle", {
        pin("vehicle", "int", false), pin("found", "bool", true), pin("speedCmS", "float", true),
        pin("x", "float", true), pin("y", "float", true), pin("z", "float", true), pin("yaw", "float", true)}});
    t.push_back({"AN_VehicleSetPose", "Vehicle Set Pose", "Vehicle", {
        pin("exec", "exec", false), pin("vehicle", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("yaw", "float", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleDestroy", "Vehicle Destroy", "Vehicle", {
        pin("exec", "exec", false), pin("vehicle", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AN_VehicleWheelContact", "Vehicle Wheel Contact", "Vehicle", {
        pin("vehicle", "int", false), pin("index", "int", false), pin("contact", "bool", true)}});
}
